<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import {get,post} from '../api/client';import type {ReturnGroup} from '../types';import {number,percent} from '../utils/format';import AppModal from '../components/AppModal.vue';import {Anchor,Scale} from 'lucide-vue-next'
const groups=ref<ReturnGroup[]>([]),active=ref<ReturnGroup|null>(null),reconcileGroup=ref<ReturnGroup|null>(null),message=ref(''),error=ref('')
const exitForm=reactive({total_quantity:0,exit_price:'',exit_time:new Date().toISOString().slice(0,16),total_fee:'5',allocations:[] as {voyage_id?:number;voyage_no:string;quantity:number}[]})
const brokerQty=ref(0),reconcileResult=ref<any>(null)
async function load(){try{groups.value=await get<ReturnGroup[]>('/api/returns/ready')}catch(e){error.value=(e as Error).message}}
async function openExit(g:ReturnGroup){active.value=g;const voyages:any[]=await get('/api/voyages');exitForm.allocations=g.ready_voyages.map(v=>({voyage_id:voyages.find(x=>x.voyage_no===v.voyage_no)?.id,voyage_no:v.voyage_no,quantity:v.remaining_quantity}));exitForm.total_quantity=g.ready_quantity;exitForm.exit_price=g.ready_voyages[0]?.monitor_price||''}
async function submitExit(){if(!active.value)return;try{await post('/api/exits',{symbol:active.value.symbol,exit_time:new Date(exitForm.exit_time).toISOString(),exit_price:exitForm.exit_price,total_quantity:exitForm.total_quantity,total_fee:exitForm.total_fee,allocations:exitForm.allocations.map(a=>({voyage_id:a.voyage_id,quantity:a.quantity}))});active.value=null;message.value='返航记录已保存，航次与舱位状态已更新。';await load()}catch(e){error.value=(e as Error).message}}
async function reconcile(){if(!reconcileGroup.value)return;reconcileResult.value=await post('/api/reconcile',{symbol:reconcileGroup.value.symbol,broker_quantity:brokerQty.value})}
onMounted(load)
</script>
<template><div class="page returns-page"><header class="returns-page-header"><div><p class="section-kicker">LANDING SETTLEMENT · 返航中心</p><h1>待返航航次</h1><p>仅列出行情有效、已可卖且达到目标收益的航次。确认成交后，系统按你指定的分配完成归档。</p></div><div class="return-count"><span>READY TO RETURN</span><b>{{groups.reduce((total,group)=>total+group.ready_voyages.length,0)}}</b></div></header><p v-if="message" class="success-banner">{{message}}</p><p v-if="error" class="error-banner">{{error}}</p><div v-if="!groups.length" class="panel empty large"><Anchor :size="30"/><h2>暂无可返航航次</h2><p>系统会持续根据买一价和净收益线监控。</p></div><section v-for="g in groups" :key="g.symbol" class="return-group panel"><header><div><p class="eyebrow">{{g.symbol}}</p><h2>{{g.name}}</h2></div><div class="system-position"><span>系统总持仓</span><b>{{number(g.system_total_quantity)}} 份</b></div></header><div class="allocation-list"><div v-for="v in g.ready_voyages" :key="v.voyage_no"><b>{{v.voyage_no}}</b><span>{{number(v.remaining_quantity)}} 份</span><span class="positive">{{percent(v.net_return)}}</span><i class="status ready">可返航</i></div></div><footer><div><span>当前可返航</span><strong>{{number(g.ready_quantity)}} <small>份</small></strong></div><div class="button-group"><button class="secondary" @click="reconcileGroup=g;brokerQty=g.system_total_quantity"><Scale :size="16"/>持仓核对</button><button class="primary" @click="openExit(g)">记录返航</button></div></footer></section><AppModal v-if="active" :title="`记录返航 · ${active.symbol}`" eyebrow="LANDING SETTLEMENT" variant="settlement" @close="active=null"><form class="form-grid" @submit.prevent="submitExit"><label>实际卖出份额<input v-model.number="exitForm.total_quantity" type="number" min="1" required/></label><label>成交均价<input v-model="exitForm.exit_price" required/></label><label>成交时间<input v-model="exitForm.exit_time" type="datetime-local" required/></label><label>费用<input v-model="exitForm.total_fee" required/></label><div class="allocation-editor"><h3>航次分配</h3><p>分配合计必须与实际卖出份额一致，系统不会自动 FIFO。</p><label v-for="a in exitForm.allocations" :key="a.voyage_no"><span>{{a.voyage_no}}</span><input v-model.number="a.quantity" type="number" min="1"/></label><div class="allocation-total"><span>分配合计</span><b>{{number(exitForm.allocations.reduce((s,a)=>s+a.quantity,0))}} 份</b></div></div><button class="primary full">确认保存返航</button></form></AppModal><AppModal v-if="reconcileGroup" :title="`持仓核对 · ${reconcileGroup.symbol}`" eyebrow="POSITION RECONCILIATION" @close="reconcileGroup=null;reconcileResult=null"><div class="reconcile-box"><div><span>系统</span><b>{{number(reconcileGroup.system_total_quantity)}}</b></div><label>券商当前份额<input v-model.number="brokerQty" type="number" min="0"/></label><button class="secondary full" @click="reconcile">开始核对</button><div v-if="reconcileResult" :class="['reconcile-result',reconcileResult.matched?'matched':'mismatch']"><strong>{{reconcileResult.matched?'一致':'存在差异'}}</strong><span>差异 {{number(reconcileResult.difference)}} 份</span><small>系统不会自动修正账本。</small></div></div></AppModal></div></template>

<style scoped>
.returns-page{max-width:1120px}.returns-page-header{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:24px;padding-bottom:20px;border-bottom:1px solid var(--line)}.returns-page-header h1{margin:5px 0 6px;font-size:25px;letter-spacing:-.03em}.returns-page-header p:last-child{max-width:680px;margin:0;color:var(--muted-2);font-size:13px;line-height:1.6}.return-count{display:grid;justify-items:end;padding-left:18px;border-left:2px solid var(--tower-green)}.return-count span{color:var(--muted-2);font-size:9px;font-weight:700;letter-spacing:.12em}.return-count b{color:var(--tower-green);font-size:28px;font-variant-numeric:tabular-nums}@media(max-width:640px){.returns-page-header{align-items:flex-start;flex-direction:column}.return-count{justify-items:start}}
</style>
